  background: #fff; color: #111827; width: 100%; min-height: 40px;
}
input[aria-invalid="true"] { border-color: #b91c1c; border-width: 2px; }
.error { color: #b91c1c; font-size: 0.875rem; margin: 0; }
:focus-visible { outline: 3px solid #1d4ed8; outline-offset: 2px; }

.btn {
  font: inherit; padding: 8px 14px; min-height: 40px; border-radius: 6px; cursor: pointer;
  border: 1px solid #6b7280; background: #fff; color: #111827;
}
.btn:hover:not(:disabled) { background: #f3f4f6; }
.btn:disabled { opacity: 0.6; cursor: not-allowed; }
.btn.primary { background: #1d4ed8; border-color: #1d4ed8; color: #fff; }
.btn.primary:hover:not(:disabled) { background: #1e40af; }
.btn.danger { color: #b91c1c; border-color: #b91c1c; }
.btn.danger-solid { background: #b91c1c; border-color: #b91c1c; color: #fff; }
