th { font-size: 0.85rem; color: #374151; background: #f9fafb; }
.num { text-align: right; font-variant-numeric: tabular-nums; }
.actions { display: flex; gap: 8px; }
.badge { display: inline-block; padding: 2px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 600; }
.badge.pending { background: #fef3c7; color: #78350f; }
.badge.paid { background: #dbeafe; color: #1e3a8a; }
.badge.shipped { background: #d1fae5; color: #064e3b; }
.badge.cancelled { background: #e5e7eb; color: #1f2937; }

.skeletons { display: grid; gap: 10px; }
.skeleton { height: 40px; border-radius: 6px; background: linear-gradient(90deg, #e5e7eb, #f3f4f6, #e5e7eb); background-size: 200% 100%; animation: sh 1.4s linear infinite; }
@keyframes sh { to { background-position: -200% 0; } }
@media (prefers-reduced-motion: reduce) { .skeleton { animation: none; } }

dialog { border: 1px solid #9ca3af; border-radius: 10px; padding: 20px; width: min(440px, calc(100vw - 32px)); color: #111827; }
dialog::backdrop { background: rgba(17, 24, 39, 0.6); }
.dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

