.error { color: #b91c1c; font-size: 0.875rem; margin: 0; }
:focus-visible { outline: 3px solid #1d4ed8; outline-offset: 2px; }

.btn {
  font: inherit; padding: 8px 14px; min-height: 40px; border-radius: 6px; cursor: pointer;
  border: 1px solid #6b7280; background: #fff; color: #111827;
}
.btn:hover:not(:disabled) { background: #f3f4f6; }
.btn:disabled { opacity: 0.6; cursor: not-allowed; }
.btn.primary { background: #1d4ed8; border-color: #1d4ed8; color: #fff; }
.btn.primary:hover:not(:disabled) { background: #1e40af; }
.btn.danger { color: #b91c1c; border-color: #b91c1c; }
.btn.danger-solid { background: #b91c1c; border-color: #b91c1c; color: #fff; }
.btn.danger-solid:hover { background: #991b1b; }

table { width: 100%; border-collapse: collapse; }
th, td { text-align: left; padding: 10px 8px; border-bottom: 1px solid #e5e7eb; }
th { font-size: 0.85rem; color: #374151; background: #f9fafb; }
.num { text-align: right; font-variant-numeric: tabular-nums; }
.actions { display: flex; gap: 8px; }
.badge { display: inline-block; padding: 2px 10px; border-radius: 999px; font-size: 0.85rem; font-weight: 600; }
.badge.pending { background: #fef3c7; color: #78350f; }
.badge.paid { background: #dbeafe; color: #1e3a8a; }
.badge.shipped { background: #d1fae5; color: #064e3b; }
.badge.cancelled { background: #e5e7eb; color: #1f2937; }

.skeletons { display: grid; gap: 10px; }
.skeleton { height: 40px; border-radius: 6px; background: linear-gradient(90deg, #e5e7eb, #f3f4f6, #e5e7eb); background-size: 200% 100%; animation: sh 1.4s linear infinite; }
@keyframes sh { to { background-position: -200% 0; } }
@media (prefers-reduced-motion: reduce) { .skeleton { animation: none; } }

dialog { border: 1px solid #9ca3af; border-radius: 10px; padding: 20px; width: min(440px, calc(100vw - 32px)); color: #111827; }
dialog::backdrop { background: rgba(17, 24, 39, 0.6); }
.dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

@media (max-width: 720px) {
  main { padding: 16px 12px; }
  table, thead, tbody, tr, th, td { display: block; }
  thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
  tr { border: 1px solid #d1d5db; border-radius: 8px; margin-bottom: 12px; padding: 4px 0; }
  td { display: flex; justify-content: space-between; align-items: center; gap: 12px; border-bottom: 0; padding: 6px 12px; text-align: right; }
  td::before { content: attr(data-label); font-weight: 600; color: #374151; text-align: left; }
  td.actions { justify-content: flex-end; }
  td.actions::before { display: none; }
}
